{
  "items": [
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "Liouville",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "definition",
      "type": "ℝ → Prop"
    },
    {
      "name": "transcendental_liouvilleNumber",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleNumber",
      "kind": "theorem",
      "type": "∀ {m : ℕ}, 2 ≤ m → Transcendental ℤ (liouvilleNumber ↑m)"
    },
    {
      "name": "Liouville.transcendental",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Liouville x → Transcendental ℤ x"
    },
    {
      "name": "liouvilleWith_one",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ (x : ℝ), LiouvilleWith 1 x"
    },
    {
      "name": "setOf_liouville_eq_iInter_iUnion",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Residual",
      "kind": "theorem",
      "type": "{x | Liouville x} = ⋂ n, ⋃ a, ⋃ b, ⋃ (_ : 1 < b), Metric.ball (↑a / ↑b) (1 / ↑b ^ n) \\ {↑a / ↑b}"
    },
    {
      "name": "forall_liouvilleWith_iff",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, (∀ (p : ℝ), LiouvilleWith p x) ↔ Liouville x"
    },
    {
      "name": "LiouvilleWith.mono",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p q x : ℝ}, LiouvilleWith p x → q ≤ p → LiouvilleWith q x"
    }
  ]
}
